import {money} from './engine.js';
import {historyTabs} from './record-view.js';
import {feedbackView} from './feedback-view.js';
import {cpuCareersView} from './career-view.js';

const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={fixed:'資産確定',cut:'ロスカット',empty:'資金枯渇',debt:'負債退場'};
const signed=value=>`${BigInt(value)>0n?'＋':''}${money(value)}`;
const tone=value=>BigInt(value)>0n?'positive':BigInt(value)<0n?'negative':'';
const metric=(label,value,key)=>`<div><dt>${label}</dt><dd data-stat="${key}">${value}</dd></div>`;
const amount=(value,signedValue=false)=>value===null?'—':signedValue?signed(value):money(value);
const count=value=>`${value.toLocaleString('ja-JP')}回`;
const date=value=>new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value));

function recentGame(game){
  const winners=game.players.filter(p=>game.winnerIds.includes(p.id)),owner=game.players.find(p=>p.id===game.ownerPlayerId&&p.kind==='human');
  const pnl=owner?String(BigInt(owner.wealth)-BigInt(owner.initial)):null;
  return `<article class="stats-game" data-history-id="${escape(game.id)}"><div class="stats-game-heading"><time datetime="${escape(game.endedAt)}">${date(game.endedAt)}</time><strong>${escape(game.stage.name)}</strong></div><p class="stats-game-mode">${game.playMode==='solo'?'CPU対戦':'対面'} · ${game.players.length}人 · ${game.endedRound} / ${game.maxRounds}ラウンド</p><p class="stats-game-winner">${winners.length?`${winners.length>1?'同率優勝':'優勝'}：${winners.map(p=>`${escape(p.name)}${p.kind==='cpu'?'（CPU）':''}`).join('・')}`:'勝者なし'}</p>${owner?`<div class="stats-game-personal"><span>あなたの最終資産<strong class="${tone(owner.wealth)}">${money(owner.wealth)}</strong></span><span>損益<strong class="${tone(pnl)}">${signed(pnl)}</strong></span></div>`:''}<details class="stats-game-players"><summary>参加者の結果（${game.players.length}人）</summary>${game.players.map(p=>`<div class="stats-roster-row"><strong>${escape(p.name)} ${p.kind==='cpu'?'<span class="cpu-tag">CPU</span>':p.id===game.ownerPlayerId?'<span class="cpu-tag">あなた</span>':''}</strong><strong class="${tone(p.wealth)}">${money(p.wealth)}</strong><span>${labels[p.status]}${game.winnerIds.includes(p.id)?' · 優勝':''}</span><span>最高 ${money(p.peak)} · 最大取引額 ${money(p.maxPosition)}</span></div>`).join('')}</details><a class="stats-link record-open-link" href="#match/${escape(game.id)}?from=stats">試合の記録を見る →</a></article>`;
}

export function statisticsView({state,data,error='',pendingCount=0,hasGame=false}){
  const head=`<div class="stats-top"><h1>戦績</h1><a href="#" class="text-button stats-link">${hasGame?'ゲームに戻る':'スタート画面へ'}</a></div>${historyTabs('stats')}`;
  if(state==='loading')return `<section class="surface stats-surface">${head}<p class="stats-message" role="status">保存済みの戦績を読み込み中…</p></section>`;
  if(state==='error')return `<section class="surface stats-surface">${head}<p class="stats-message" role="alert">${escape(error||'戦績を読み込めませんでした。')}</p><button class="secondary" data-action="reload-statistics">再読み込み</button></section>`;
  const s=data.lifetime;
  return `<div class="stats-layout"><section class="surface stats-surface">${head}<p class="stats-scope">あなたの生涯戦績 · CPU対戦<br>対面の試合は履歴に残ります。本人未指定のため、生涯戦績には含めません。</p>${pendingCount?`<p class="stats-pending" role="status">保存完了を確認できていない試合が${pendingCount}件あります。<button class="text-button" data-action="retry-records">保存を再試行</button></p>`:''}<div class="stats-hero"><div class="stats-comparison"><div><span>1ゲームの最高最終資産</span><strong class="${s.highestFinal!==null?tone(s.highestFinal):''}" data-stat="highestFinal">${amount(s.highestFinal)}</strong></div><div><span>生涯損益</span><strong class="${tone(s.pnlTotal)}" data-stat="pnlTotal">${signed(s.pnlTotal)}</strong></div></div><dl class="stats-capital">${metric('投入元本相当',money(s.initialTotal),'initialTotal')}${metric('最終資産合計',money(s.finalTotal),'finalTotal')}</dl></div><dl class="stats-overview">${metric('総プレイ回数',count(s.plays),'plays')}${metric('優勝回数',count(s.wins),'wins')}${metric('優勝率',s.winRateTenths===null?'—':`${(s.winRateTenths/10).toFixed(1)}%`,'winRate')}</dl>${!s.plays?`<p class="stats-empty">まだCPU対戦の戦績がありません。${data.totalSavedGames?'対面の記録は、下のゲーム履歴で確認できます。':'ゲームを最後まで遊ぶと、ここに成績が残ります。'}</p>`:''}<section class="stats-section"><h2>勝敗と終了</h2><dl class="stats-metrics">${metric('元本以上で終了',count(s.atOrAboveInitial),'atOrAboveInitial')}${metric('元本割れ',count(s.belowInitial),'belowInitial')}${metric('資金枯渇・ロスカット',count(s.fundsDepleted),'fundsDepleted')}${metric('負債退場',count(s.debtExits),'debtExits')}</dl></section><details class="stats-detail"><summary>資産の記録</summary><dl class="stats-metrics">${metric('平均最終資産',amount(s.averageFinal),'averageFinal')}${metric('1ゲーム平均損益',amount(s.averagePnl,true),'averagePnl')}${metric('最高到達資産',amount(s.highestPeak),'highestPeak')}${metric('最大取引額',s.plays?money(s.maxPosition):'—','maxPosition')}${metric('最大1ラウンド利益',s.plays?money(s.maxRoundProfit):'—','maxRoundProfit')}${metric('最大1ラウンド損失',s.plays?money(s.maxRoundLoss):'—','maxRoundLoss')}${metric('最大負債',s.plays?money(s.maxDebt):'—','maxDebt')}${metric('最大ドローダウン',s.plays?money(s.maxDrawdown):'—','maxDrawdown')}</dl><p class="stats-definition">損失・負債は減った金額で表示。ドローダウンは、それまでの最高資産からの最大減少額（負債を含む）。平均は1,000円単位で四捨五入します。</p></details><details class="stats-detail"><summary>倍率の記録</summary><dl class="stats-metrics">${metric('最大レバレッジ',s.plays?`${s.maxLeverage}倍`:'—','maxLeverage')}${metric('100倍使用回数',count(s.uses100),'uses100')}${metric('50倍以上使用回数',count(s.uses50Plus),'uses50Plus')}</dl></details><p class="stats-definition">同率優勝も1回として集計。元本割れには0円・負債での終了を含みます。資金枯渇には通常相場のロスカットも含みます。</p></section>${feedbackView(data.feedback)}${cpuCareersView(data.cpuCareers)}<section class="surface stats-surface stats-recent"><h2>最近のゲーム</h2><p class="stats-history-count">保存済み ${data.totalSavedGames.toLocaleString('ja-JP')}ゲーム · ${data.totalSavedGames>10?'最新10件':'全件'}</p>${data.recentGames.length?data.recentGames.map(recentGame).join(''):'<p class="stats-empty">保存したゲームはまだありません。</p>'}</section></div>`;
}
